# prompts.py - cicada-reunion pictures (gpt-image-2.5-sunburst, 1K, LOW, 1 variation, NO references). Blocks from memory/STYLE.md.
import json, re
src = open('../butt-breath/prompts.py').read()
CHAR, OBJ, BG = [eval(re.search(r'^' + n + r' = (".*?")$', src, re.M).group(1)) for n in ['CHAR', 'OBJ', 'BG']]
KEY = "Isolated on a perfectly flat, uniform, solid pure {c} background that fills the whole picture edge to edge: no shadow, no ground, no floor line, no gradient, no vignette, no border, no other objects. The whole subject in frame with a clear margin on every side."
G, M = KEY.format(c='green (#00FF00)'), KEY.format(c='magenta (#FF00FF)')
THREE = "Three DIFFERENT poses of the same character side by side in one row, all three the same size, with wide empty gaps between them, every copy full body, no ground drawn, bold clean thick outlines. "
P = {}
P['guy'] = THREE + "LEFT copy: kneeling on both knees, bent forward, side view facing to the RIGHT, one hand cupped behind the ear, listening closely to something below, curious eyebrows, mouth a small 'o'. MIDDLE copy: facing the viewer, both hands pressed flat over the sides of the head where ears would be, eyes squeezed shut as '> <', mouth a wide wavy grimace with teeth. RIGHT copy: facing the viewer, a helpless shrug: both arms out to the sides with open palms up, eyebrows raised, a crooked awkward smile. Whole bodies in frame with a margin. " + CHAR + " " + M
P['bugs'] = "Three DIFFERENT cute cartoon cicadas side by side in one row, all the same size, with wide empty gaps between them. LEFT: a cicada nymph, side view facing to the RIGHT, standing upright on its back legs like a little person, a chubby segmented tan-brown body (#B98A4E with a #94693A shade), big digging front claws raised, small round dark eyes, a cheerful curious face. MIDDLE: an adult periodical cicada, top view, a black body (#2A2A2A), big round bright red eyes (#E8392B), orange veins (#F29A2E) in two pairs of clear pale glassy wings (#E8F1F5) folded over the back. RIGHT: the same adult cicada front view, wings spread wide open, singing with a big open mouth and a pink tongue, happy closed eyes as curved lines over the red eyes. " + OBJ + " no letters, no numbers. " + M
P['props'] = "Three DIFFERENT cartoon objects side by side in one row with wide empty gaps between them. LEFT (widest): a red push lawn mower in side view facing to the LEFT, flat red body (#E2402F with a #B8301F shade), a black long handle, four black wheels with grey hubs. MIDDLE: a paper wall calendar with a blank white page (no numbers, no writing) and two black rings on top. RIGHT: an old-fashioned black three-cornered tricorn hat (#2B2B2B) with a thin gold trim (#E0B54A). " + OBJ + " no characters, no letters, no numbers. " + G
P['under'] = "A vertical cut-away picture of the ground: the top 22 % is a pale blue spring sky (#BEE3F2) with a strip of bright green grass (#7CC46A) on the surface at about 22 % of the height; below it brown soil (#8B5E3C) with darker soil layers (#6E4A2E), a few simple round pebbles and thin pale tree roots (#D9B98A) coming down from the top; in the middle of the soil an empty smooth oval underground chamber (#5A3C25) with a narrow tunnel going straight up from it to the grass. " + BG + " no text, no signs, no people, no animals, no insects."
P['tree'] = "A vertical picture of a sunny park in early summer: one big tree with a thick brown trunk (#8A5A35) in the middle going up from the bottom, wide rounded green leafy crown (#5DA853, #7CC46A) filling the top half, grass (#8ED16F) on the ground in the bottom 25 %, a pale blue sky (#BEE3F2) behind, a few small bushes on the sides. Open flat grass in the lower middle. " + BG + " no text, no signs, no people, no animals, no insects."
json.dump(P, open('prompts.json', 'w'), indent=1)
with open('prompts.md', 'w') as f:
    f.write('# cicada-reunion - picture prompts (gpt-image-2.5-sunburst, 1K, LOW, 1 variation, no references)\n\n')
    for k, v in P.items(): f.write(f'## {k} ({"2:3" if k in ("under","tree") else "3:2"})\n{v}\n\n')
for k, v in P.items(): print(k, len(v))
